package com.saasquatch.intelligence.entity;
import jakarta.persistence.*; import java.util.*; import com.fasterxml.jackson.annotation.JsonIgnore;
@Entity @Table(name="leads") public class Lead { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private Company company; private String title; private String contactName; private String contactEmail; private String seniority; private boolean decisionMaker; private Integer dataConfidence=80; @JsonIgnore @OneToMany(mappedBy="lead",cascade=CascadeType.ALL,orphanRemoval=true) private List<BuyingSignal> signals=new ArrayList<>(); public Long getId(){return id;} public Company getCompany(){return company;} public void setCompany(Company v){company=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getContactName(){return contactName;} public void setContactName(String v){contactName=v;} public String getContactEmail(){return contactEmail;} public void setContactEmail(String v){contactEmail=v;} public String getSeniority(){return seniority;} public void setSeniority(String v){seniority=v;} public boolean isDecisionMaker(){return decisionMaker;} public void setDecisionMaker(boolean v){decisionMaker=v;} public Integer getDataConfidence(){return dataConfidence;} public void setDataConfidence(Integer v){dataConfidence=v;} public List<BuyingSignal> getSignals(){return signals;} }